package br.com.conectatea.sessao.domain; import jakarta.persistence.*; import java.time.*; @Entity @Table(name="historico_sessao") public class HistoricoSessao{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="sessao_id")private Long sessao;@Column(name="autor_usuario_id")private Long autor;private String tipo;@Column(name="status_anterior")private String anterior;@Column(name="status_novo")private String novo;@Column(name="inicio_anterior")private OffsetDateTime inicioAnterior;@Column(name="inicio_novo")private OffsetDateTime inicioNovo;private String motivo;@Column(name="criado_em")private Instant criado=Instant.now();protected HistoricoSessao(){}public HistoricoSessao(Long s,Long a,String t,String old,String next,OffsetDateTime before,OffsetDateTime after,String m){sessao=s;autor=a;tipo=t;anterior=old;novo=next;inicioAnterior=before;inicioNovo=after;motivo=m;}}
